import { copyFileSync, existsSync, mkdirSync, readFileSync, rmSync, writeFileSync } from "node:fs";
import { createHash } from "node:crypto";
import { spawn } from "node:child_process";
import { homedir, tmpdir } from "node:os";
import { join, resolve } from "node:path";
import process from "node:process";

export const CODEX_HOME_MODES = ["isolated", "inherit"];
export const CODEX_AUTH_MODES = ["inherit", "env", "none"];
const RUNTIME_PRODUCER = /^[A-Za-z0-9][A-Za-z0-9._-]{0,127}$/;

function pushOptionalPair(args, flag, value) {
	if (value) {
		args.push(flag, value);
	}
}

export function codexArgs(options, schemaFile, outputFile) {
	const sessionMode = options.codexSessionMode ?? "ephemeral";
	const args = [
		"exec",
		"-C",
		options.workspace,
		"--sandbox",
		options.sandbox,
	];
	if ((options.codexHomeMode ?? "inherit") === "isolated") {
		args.push("--ignore-user-config");
	}
	if (sessionMode === "ephemeral") {
		args.push("--ephemeral");
	}
	args.push("--output-schema", schemaFile, "-o", outputFile);
	pushOptionalPair(args, "--model", options.codexModel ?? options.model);
	const effort = options.codexReasoningEffort ?? options.reasoningEffort;
	if (effort) {
		args.push("-c", `model_reasoning_effort="${effort}"`);
	}
	for (const override of options.codexConfigOverrides ?? []) {
		args.push("-c", override);
	}
	args.push("-");
	return args;
}

function codexSourceHome(env = process.env) {
	return env.CODEX_HOME ? resolve(env.CODEX_HOME) : join(homedir(), ".codex");
}

function hasEnvCodexAuth(env = process.env) {
	return Boolean(env.OPENAI_API_KEY);
}

function authMissingMessage(authMode, sourceHome) {
	if (authMode === "env") {
		return "The codex_exec runner cannot authenticate: --codex-auth-mode env was selected but OPENAI_API_KEY is not set.";
	}
	return `The codex_exec runner cannot authenticate: isolated CODEX_HOME could not inherit ${sourceHome}/auth.json and OPENAI_API_KEY is not set.`;
}

function repoIdentity(repoRoot) {
	if (!repoRoot) {
		return null;
	}
	return createHash("sha256").update(resolve(repoRoot), "utf-8").digest("hex").slice(0, 16);
}

export function temporaryOwnedRuntimeHome(options, producer, env = process.env) {
	if (typeof producer !== "string" || !RUNTIME_PRODUCER.test(producer)) {
		throw new Error(`temporary runtime producer must be a simple token: ${producer}`);
	}
	const runtimeRoot = env.CHARNESS_RUNTIME_ROOT
		? resolve(env.CHARNESS_RUNTIME_ROOT)
		: join(tmpdir(), "charness");
	const runId = `${process.pid}-${Date.now()}-${Math.random().toString(16).slice(2)}`;
	const createdAt = new Date().toISOString();
	const path = join(runtimeRoot, "scratch", producer, runId);
	mkdirSync(join(runtimeRoot, "scratch", producer), { recursive: true });
	mkdirSync(path);
	writeFileSync(
		join(path, ".charness-owner.json"),
		`${JSON.stringify(
			{
				schema: "charness.runtime-scratch-owner/v1",
				owner: "charness",
				producer,
				repo_root: options.repoRoot ?? null,
				repo_identity: repoIdentity(options.repoRoot),
				run_id: runId,
				pid: process.pid,
				created_at: createdAt,
				updated_at: createdAt,
				state: "active",
				retention: "scratch",
				expires_at: new Date(Date.now() + 24 * 60 * 60 * 1000).toISOString(),
			},
			null,
			2,
		)}\n`,
		"utf-8",
	);
	const lockPath = join(path, ".charness-owner.lock");
	// The Python registry uses fcntl.flock, so a marker file alone is not a lock
	// it can observe.  Keep a bounded `flock` holder for the lifetime of this
	// eval; its detached process is also what keeps an interrupted parent from
	// making the scratch root immediately reclaimable.  The expiry matches the
	// owner receipt, after which normal recovery may reclaim the evidence.
	writeFileSync(lockPath, `pid=${process.pid}\n`, { encoding: "utf-8", flag: "wx" });
	let lockProcess = null;
	if (process.platform === "linux") {
		lockProcess = spawn("flock", ["-n", lockPath, "-c", "sleep 86400"], {
			detached: true,
			stdio: "ignore",
		});
		lockProcess.unref();
	}
	const recordRunnerPid = (pid) => {
		if (!Number.isInteger(pid) || pid <= 0) {
			return;
		}
		const ownerPath = join(path, ".charness-owner.json");
		if (!existsSync(ownerPath)) {
			return;
		}
		const owner = JSON.parse(readFileSync(ownerPath, "utf-8"));
		owner.runner_pid = pid;
		owner.updated_at = new Date().toISOString();
		writeFileSync(ownerPath, `${JSON.stringify(owner, null, 2)}\n`, "utf-8");
	};
	return { path, lockProcess, recordRunnerPid };
}

function temporaryCodexHome(options, env = process.env) {
	return temporaryOwnedRuntimeHome(options, "codex-eval", env);
}

export function cleanupTemporaryOwnedHome(temporary, state = "succeeded") {
	if (!temporary) {
		return;
	}
	try {
		if (temporary.lockProcess?.pid) {
			try {
				process.kill(-temporary.lockProcess.pid, "SIGTERM");
			} catch {
				try {
					temporary.lockProcess.kill("SIGTERM");
				} catch {
					// The lock holder may have expired or already exited.
				}
			}
		}
		const ownerPath = join(temporary.path, ".charness-owner.json");
		if (existsSync(ownerPath)) {
			const owner = JSON.parse(readFileSync(ownerPath, "utf-8"));
			owner.state = state;
			owner.updated_at = new Date().toISOString();
			writeFileSync(ownerPath, `${JSON.stringify(owner, null, 2)}\n`, "utf-8");
		}
	} finally {
		rmSync(temporary.path, { recursive: true, force: true });
	}
}

function withPreflightBlocker(runtime, summary) {
	return {
		...runtime,
		preflightBlocker: {
			blockerKind: "runner_auth_missing",
			summary,
		},
	};
}

export function prepareCodexRuntimeEnv(options, baseEnv = process.env) {
	const authMode = options.codexAuthMode ?? "inherit";
	const homeMode = options.codexHomeMode ?? "inherit";
	// `none` must not point a child at the operator's credential-bearing
	// CODEX_HOME.  Force an owned empty home for that combination; merely
	// deleting OPENAI_API_KEY still lets the CLI discover ~/.codex/auth.json.
	const effectiveHomeMode = authMode === "none" && homeMode === "inherit" ? "isolated" : homeMode;
	if (effectiveHomeMode === "inherit") {
		const runtime = {
			env: baseEnv,
			cleanup: null,
			preflightBlocker: null,
			telemetry: {
				codex_home_mode: "inherit",
				codex_home_isolated: false,
				...(baseEnv.CODEX_HOME ? { codex_home_path: baseEnv.CODEX_HOME } : {}),
			},
		};
		if (authMode === "env" && !hasEnvCodexAuth(baseEnv)) {
			return withPreflightBlocker(runtime, authMissingMessage(authMode, codexSourceHome(baseEnv)));
		}
		return runtime;
	}

	const configuredHome = options.codexHome ? resolve(options.codexHome) : null;
	if (authMode === "none" && configuredHome) {
		return withPreflightBlocker(
			{
				env: { ...baseEnv },
				cleanup: null,
				preflightBlocker: null,
				telemetry: {
					codex_home_mode: "custom",
					codex_home_isolated: false,
				},
			},
			"The codex_exec runner cannot enforce --codex-auth-mode none with a custom CODEX_HOME; remove --codex-home or choose an authenticated mode.",
		);
	}
	const temporary = configuredHome ? null : temporaryCodexHome(options, baseEnv);
	const codexHome = configuredHome ?? temporary.path;
	mkdirSync(codexHome, { recursive: true });
	const cleanup = configuredHome
		? null
		: (state = "succeeded") => {
			cleanupTemporaryOwnedHome(temporary, state);
		};
	const env = {
		...baseEnv,
		CODEX_HOME: codexHome,
		...(temporary ? { CHARNESS_OWNED_SCRATCH_ROOT: temporary.path } : {}),
	};
	if (authMode === "none") {
		for (const key of ["OPENAI_API_KEY", "CODEX_API_KEY"]) {
			delete env[key];
		}
	}
	const runtime = {
		env,
		cleanup,
		recordRunnerPid: temporary?.recordRunnerPid ?? null,
		preflightBlocker: null,
		telemetry: {
			codex_home_mode: configuredHome ? "custom" : "isolated",
			codex_home_isolated: true,
			codex_home_path: codexHome,
		},
	};

	if (authMode === "inherit") {
		const sourceHome = codexSourceHome(baseEnv);
		const sourceAuthFile = join(sourceHome, "auth.json");
		const destinationAuthFile = join(codexHome, "auth.json");
		if (existsSync(sourceAuthFile) && resolve(sourceAuthFile) !== resolve(destinationAuthFile)) {
			copyFileSync(sourceAuthFile, destinationAuthFile);
		} else if (!existsSync(destinationAuthFile) && !hasEnvCodexAuth(baseEnv)) {
			return withPreflightBlocker(runtime, authMissingMessage(authMode, sourceHome));
		}
	}
	if (authMode === "env" && !hasEnvCodexAuth(baseEnv)) {
		return withPreflightBlocker(runtime, authMissingMessage(authMode, codexSourceHome(baseEnv)));
	}
	return runtime;
}

export function codexFailureBlockerKind(stderr = "") {
	const text = String(stderr).toLowerCase();
	const authFailure = [
		"401 unauthorized",
		"missing bearer or basic authentication",
		"not authenticated",
		"authentication error",
		"login required",
	].some((pattern) => text.includes(pattern));
	return authFailure ? "runner_auth_missing" : "runner_execution_failed";
}

