function terminateProcessGroup(pid) {
	if (!Number.isInteger(pid) || pid <= 0 || process.platform === "win32") {
		return;
	}
	try {
		// `detached: true` makes the child the process-group leader on POSIX.
		// A timeout must kill the group, not just the CLI process, or a tool
		// descendant can keep the owned scratch home live after the parent returns.
		process.kill(-pid, "SIGTERM");
	} catch {
		// The direct child may already have exited during timeout collection.
	}
	try {
		process.kill(-pid, "SIGKILL");
	} catch {
		// Best effort: the registry still retains an owner whose process is live.
	}
}

