		}
	}
	return {
		env,
		recordRunnerPid: temporary?.recordRunnerPid ?? null,
		cleanup: (state = "succeeded") => {
			if (temporary) {
				cleanupTemporaryOwnedHome(temporary, state);
				return;
			}
			rmSync(home, { recursive: true, force: true });
		},
	};
}

