SKIP_PARTS = frozenset({"__pycache__", "generated", "vendor"})
TEMPFILE_APIS = {
    "TemporaryDirectory": "directory",
    "mkdtemp": "directory",
    "mkstemp": "atomic-file",
    "NamedTemporaryFile": "anonymous-file",
    "TemporaryFile": "anonymous-file",
