    "skills/public/quality/scripts/inventory_skill_ergonomics.py": {
      "states": [
        "prose_review_status"
      ],
      "visibility": [
        "structured_warning"
      ],
      "evidence_terms": [
        "prose_review_status",
        "advisories"
      ],
      "rationale": "The compact skill ergonomics summary carries prose-review-required state and the advisory list so reviewers do not need the full per-skill payload to see the non-blocking attention state."
    },
    "skills/public/quality/scripts/quality_declaration_lifecycle.py": {
      "states": [
        "not_configured"
      ],
      "visibility": [
        "operator_summary",
        "terminal_payload"
      ],
      "evidence_terms": [
        "not-configured",
        "gaps"
      ],
      "rationale": "The declaration lifecycle is embedded in the planner payload, and the prescribed default human rendering prints its status, every gap, every routed command, and each not-run execution state. A missing adapter is therefore a typed non-verdict rather than a clean plan."
    },
    "skills/public/quality/scripts/skill_ergonomics_lib.py": {
      "states": [
        "prose_review_status"
      ],
      "visibility": [
        "structured_warning"
      ],
      "evidence_terms": [
        "prose_review_status",
        "advisories"
      ],
      "rationale": "Skill ergonomics prose-review-required states produce advisory payloads consumed by quality artifacts."
    },
    "skills/public/quality/scripts/validate_skill_ergonomics.py": {
      "states": [
        "not_configured",
        "skipped"
      ],
      "visibility": [
        "structured_warning",
        "stdout_attention"
      ],
      "evidence_terms": [
        "WARNING:",
        "skill_ergonomics_gate_rules_empty"
      ],
      "rationale": "Empty or disabled skill ergonomics enforcement remains exit-zero but emits warnings. Since the 2026-08-14 --json removal the payload also names the state directly as `verdict: not-configured`, and each warning carries an `attention` field holding the `WARNING:` marker that previously existed only in the retired human renderer -- so an exit-zero run still says enforcement was never configured rather than that it passed."
    },
    "skills/public/release/scripts/check_fresh_checkout_probes.py": {
      "states": [
        "not_configured"
      ],
      "visibility": [
        "artifact_visible",
        "stdout_attention"
      ],
      "evidence_terms": [
        "release adapter declares no fresh_checkout_probes"
      ],
      "rationale": "Release fresh-checkout absence is written into the release artifact and plain output."
    },
    "skills/public/release/scripts/check_requested_review_gate.py": {
      "states": [
        "advisory-only",
        "not_configured"
      ],
      "visibility": [
        "structured_warning",
        "stdout_attention"
      ],
      "evidence_terms": [
        "WARNING:",
        "requested_review_commands is empty"
      ],
      "rationale": "Release requested-review absence remains non-blocking only with an explicit warning."
    },
    "skills/public/release/scripts/publish_release_adapter_preflight.py": {
      "states": [
        "not_configured",
        "not_evaluable"
      ],
      "visibility": [
        "artifact_visible"
      ],
      "evidence_terms": [
        "not_configured",
        "not_evaluable"
      ],
      "rationale": "Release adapter focused preflight records not_configured/not_evaluable as release-artifact-visible non-claims when a changed adapter cannot run focused commands or lacks a previous tag for field diff."
    },
    "skills/public/release/scripts/publish_release_artifact_sections.py": {
      "states": [
        "not_configured"
      ],
      "visibility": [
        "artifact_visible"
      ],
      "evidence_terms": [
        "No repo-declared fresh checkout probes were configured"
      ],
      "rationale": "Release artifact renderer. Writes the not-configured fresh-checkout status into the durable release record as prose the rung-2 human reads. The post-publish verification renderers (and the `skipped` state they must render honestly) moved to publish_release_verification_sections.py."
    },
    "skills/public/release/scripts/publish_release_post_create.py": {
      "states": [
        "not_configured",
        "skipped"
      ],
      "visibility": [
        "terminal_payload",
        "artifact_visible",
        "local_noop_not_closeout"
      ],
      "evidence_terms": [
        "refreshed",
        "failed",
        "skipped",
        "reason"
      ],
      "rationale": "run_post_publish_install_refresh returns not_configured (surfaced under install_refresh). confirm_release_via_distinct_channel (WS-1 rung-2) returns status skipped only when there is no published release URL and no adapter post_publish_distinct_channel_probe; that skipped is a TYPED, RECORDED disposition written to payload.distinct_channel_verification and rendered in the release artifact's `## Distinct-Channel Verification` section, which the human rung-2 disposition review audits. It passes the rung-1 presence floor (render-not-declare, F2a) but is never a silent clean pass — the gap is legible, not green."
    },
    "skills/public/release/scripts/publish_release_verification_sections.py": {
      "states": [
        "skipped"
      ],
      "visibility": [
        "artifact_visible"
      ],
      "evidence_terms": [
        "no distinct channel ran"
      ],
      "rationale": "Post-publish verification renderers for the release artifact. `skipped` is a distinct-channel record status this module must render HONESTLY: the branch exists precisely so the artifact stops asserting 'a channel distinct from `gh release view`' over a record where no channel ran at all (D8), rendering '**no distinct channel ran**' instead. Not a runtime status of this script -- a status it refuses to paper over."
    },
    "skills/public/release/scripts/resolve_adapter.py": {
      "states": [
        "advisory-only"
      ],
      "visibility": [
        "terminal_payload"
      ],
      "evidence_terms": [
        "requested_review_policy",
        "review skipped because"
      ],
      "rationale": "Release adapter parsing preserves requested-review advisory-only policy and skipped-review patterns for requested-review gate decisions."
    },
    "skills/public/retro/scripts/check_auto_trigger.py": {
      "states": [
        "not_configured"
      ],
      "visibility": [
        "structured_warning",
        "terminal_payload"
      ],
      "evidence_terms": [
        "configuration_status",
        "not-configured",
        "state"
      ],
      "rationale": "Same three-state probe vocabulary as `boundary_probe_lib`: `not_configured` means this repo declared no auto-retro trigger, which is a determined opt-out and exits 0, while an adapter that is absent, misspelled, or unparseable is `not-established` and exits 3. Before that split a caller polling `triggered` read every one of those worlds as a judged 'no'."
    },
    "skills/public/setup/scripts/seed_dependencies.py": {
      "states": [
        "skipped"
      ],
      "visibility": [
        "terminal_payload"
      ],
      "evidence_terms": [
        "status",
        "skipped"
      ],
      "rationale": "Dependency seeding reports skipped dependency setup as structured payload status."
    },
    "skills/public/shared/scripts/reviewer_result.py": {
      "states": [
        "skipped"
      ],
      "visibility": [
        "terminal_payload"
      ],
      "evidence_terms": [
        "skipped_oversized_records"
      ],
      "rationale": "The transcript reader caps per-record size so a pathological reviewer message cannot overflow the caller's context, and counts the records it skipped for that reason. The count is emitted as `skipped_oversized_records` in the returned payload whenever it is non-zero, so a truncated read is visible to the caller rather than silently thinner than the transcript. This is a diagnostic helper's read budget, not a quality or release closeout signal: the helper is explicitly the diagnostic floor for a stranded reviewer result, and every payload carries diagnostic_only=true plus the contract sentence saying so."
    },
    "skills/support/markdown-preview/scripts/render_markdown_preview.py": {
      "states": [
        "disabled"
      ],
      "visibility": [
        "structured_warning",
        "terminal_payload"
      ],
      "evidence_terms": [
        "Markdown preview is disabled by config."
      ],
      "rationale": "Markdown preview disabled state includes a warning in the render payload."
    },
    "skills/support/web-fetch/scripts/acquisition_trace_lib.py": {
      "states": [
        "skipped"
      ],
      "visibility": [
        "support_trace"
      ],
      "evidence_terms": [
        "status=\"skipped\""
      ],
      "rationale": "Web-fetch skipped acquisition attempts are explicit trace entries."
    },
    "scripts/task_run/task_run_completion.py": {
      "states": [
        "skipped"
      ],
      "visibility": [
        "terminal_payload"
      ],
      "evidence_terms": [
        "skipped",
        "reason",
        "changed_line_gate"
      ],
      "rationale": "_changed_line_verdict records `changed_line_gate.status: skipped` with a `reason` when a lane ended without a validated candidate, so there is nothing for the changed-line gate to judge. It is a typed, persisted field in the lane's terminal `result.json` beside `not-run` (no gate supplied) and `not-applicable` (a tree without the gate script); none of the three is `clean`, `blocking` is false only because no candidate exists, and the parent reads the status at the receipt (docs/agent-task-runs.md)."
    },
    "scripts/gates_support/runtime_root_retention.py": {
      "states": [
        "skipped"
      ],
      "visibility": [
        "artifact_visible",
        "stdout_attention"
      ],
      "evidence_terms": [
        "skipped",
        "reason",
        "retention"
      ],
      "rationale": "The runtime-root sweep records `skipped` for every entry it deliberately left alone (a running lane, a key or subtree touched within the active window, a live pytest run lock, an unverifiable salvage), each with its reason, in the JSON log under `<key>/retention/` and, for the by-hand CLI, on stderr; the standing-runner hook prints the counts on one summary line. A skip is a retention decision the operator can read, never a claim that anything was cleaned."
    }
  }
}

# charness:gate-policy scheduled-deeper-check
# Installed by charness:quality propose_mutation_testing.
# This workflow parses .agents/quality-adapter.yaml at runtime; do not hand-
# edit the mutation_testing values here — change them in the adapter instead.
# Source generalization: craken-agents/.github/workflows/mutation-tests.yml.
# Gate policy: scheduled deeper-check workflows are exempt from canonical
# CI/local gate parity because mutation testing is a periodic deeper
# analysis, not a per-commit quality gate. See
# skills/public/quality/references/maintainer-local-enforcement.md
# §Scheduled deeper-check workflows.

name: Mutation Tests

on:
  workflow_dispatch:
  pull_request:
    paths:
      - .agents/quality-adapter.yaml
      - .github/workflows/mutation-tests.yml
  schedule:
    - cron: "MUTATION_SCHEDULE_CRON_PLACEHOLDER"

permissions:
  actions: read
  contents: read
  issues: write

concurrency:
  group: mutation-tests-${{ github.ref }}
  cancel-in-progress: false

jobs:
  mutation:
    name: Mutation tests
    runs-on: ubuntu-latest
    timeout-minutes: 180
    steps:
      - name: Record mutation job outer budget
        # Inner exec timeout must not outlive this job. The wrapper caps
        # `--exec-timeout-seconds` to remaining job time minus dump reserve
        # (recurrence-class: inner-timeout-outlives-outer-budget).
        run: |
          echo "MUTATION_JOB_START_EPOCH=$(date +%s)" >> "$GITHUB_ENV"
          echo "MUTATION_JOB_TIMEOUT_SECONDS=10800" >> "$GITHUB_ENV"
      - name: Checkout
        uses: actions/checkout@v6
        with:
          fetch-depth: 0

      - name: Resolve mutation_testing adapter slots
        id: adapter
        shell: bash
        run: |
          set -euo pipefail
          ADAPTER=".agents/quality-adapter.yaml"
          if [[ ! -f "$ADAPTER" ]]; then
            echo "::error::adapter file not found at $ADAPTER"
            exit 1
          fi
          read_slot() {
            local path="$1"
            local default="$2"
            local value
            value=$(yq -r "$path // \"\"" "$ADAPTER")
            if [[ -z "$value" || "$value" == "null" ]]; then
              value="$default"
            fi
            printf '%s' "$value"
          }
          declined=$(read_slot '.mutation_testing.declined' 'false')
          if [[ "$declined" == "true" ]]; then
            echo "mutation_testing.declined is true; skipping run."
            echo "should_run=false" >> "$GITHUB_OUTPUT"
            exit 0
          fi
          full=$(read_slot '.mutation_testing.commands.full' '')
          if [[ -z "$full" ]]; then
            echo "::error::mutation_testing.commands.full is empty; nothing to run."
            exit 1
          fi
          {
            echo "should_run=true"
            echo "cmd_dry_run=$(read_slot '.mutation_testing.commands.dry_run' '')"
            echo "cmd_full=$full"
            echo "cmd_sample=$(read_slot '.mutation_testing.commands.sample' '')"
            echo "cmd_summary=$(read_slot '.mutation_testing.commands.summary' '')"
            echo "score_break=$(read_slot '.mutation_testing.score_break' '60')"
            echo "changed_quota=$(read_slot '.mutation_testing.changed_quota' '5')"
            echo "max_files=$(read_slot '.mutation_testing.max_files' '10')"
            echo "max_executable_mutants=$(read_slot '.mutation_testing.max_executable_mutants' '120')"
            echo "max_executable_mutants_per_file=$(read_slot '.mutation_testing.max_executable_mutants_per_file' '80')"
            echo "max_test_nodeids=$(read_slot '.mutation_testing.max_test_nodeids' '40')"
            echo "auto_issue_enabled=$(read_slot '.mutation_testing.auto_issue.enabled' 'false')"
            echo "auto_issue_label=$(read_slot '.mutation_testing.auto_issue.label' 'mutation-test')"
            echo "auto_issue_title=$(read_slot '.mutation_testing.auto_issue.title' 'Mutation test regression on main')"
            echo "auto_issue_marker_token=$(read_slot '.mutation_testing.auto_issue.marker_token' 'mutation-test-regression')"
            echo "summary_md=$(read_slot '.mutation_testing.report_paths.summary_md' 'reports/mutation/summary.md')"
            echo "sample_md=$(read_slot '.mutation_testing.report_paths.sample_md' 'reports/mutation/sample.md')"
            echo "run_log=$(read_slot '.mutation_testing.report_paths.log' 'reports/mutation/run.log')"
          } >> "$GITHUB_OUTPUT"

      - name: Plan run
        # NOTE: same-SHA dedup was removed.
        # Scheduled runs always execute so that stratified sampling can rotate
        # over time even when main is idle, and a real regression cannot be
        # masked by a later same-SHA "skip-success" run.
        if: steps.adapter.outputs.should_run == 'true'
        id: plan
        uses: actions/github-script@v8
        with:
          script: |
            const mode = context.eventName === 'pull_request' ? 'dry-run' : 'full';

            let basePreviousSha = '';
            if (context.eventName === 'schedule') {
              const { owner, repo } = context.repo;
              const defaultBranch = context.payload.repository.default_branch;
              const { data } = await github.rest.actions.listWorkflowRuns({
                owner,
                repo,
                workflow_id: '.github/workflows/mutation-tests.yml',
                branch: defaultBranch,
                status: 'completed',
                per_page: 10,
              });
              const previousCompleted = data.workflow_runs.find((run) => run.id !== context.runId && ['success', 'failure'].includes(run.conclusion));
              basePreviousSha = previousCompleted?.head_sha ?? '';
              core.info(previousCompleted
                ? `Previous completed mutation workflow ran at ${previousCompleted.head_sha}. Current SHA is ${context.sha}.`
                : 'No previous completed mutation workflow was found.');
            }

            core.setOutput('mode', mode);
            core.setOutput('should_run', 'true');
            core.setOutput('head_sha', context.sha);
            core.setOutput('base_sha', basePreviousSha);

      - name: Select mutation sample
        if: steps.adapter.outputs.should_run == 'true' && steps.plan.outputs.should_run == 'true' && steps.plan.outputs.mode == 'full' && steps.adapter.outputs.cmd_sample != ''
        id: sample
        env:
          MUTATION_BASE_SHA: ${{ steps.plan.outputs.base_sha }}
          MUTATION_HEAD_SHA: ${{ steps.plan.outputs.head_sha }}
          MUTATION_SAMPLE_CHANGED_QUOTA: ${{ steps.adapter.outputs.changed_quota }}
          MUTATION_SAMPLE_MAX_FILES: ${{ steps.adapter.outputs.max_files }}
          MUTATION_SAMPLE_MAX_EXECUTABLE_MUTANTS: ${{ steps.adapter.outputs.max_executable_mutants }}
          MUTATION_SAMPLE_MAX_EXECUTABLE_MUTANTS_PER_FILE: ${{ steps.adapter.outputs.max_executable_mutants_per_file }}
          MUTATION_SAMPLE_MAX_TEST_NODEIDS: ${{ steps.adapter.outputs.max_test_nodeids }}
          MUTATION_SAMPLE_SEED: ${{ github.run_id }}:${{ steps.plan.outputs.base_sha }}..${{ steps.plan.outputs.head_sha }}
        shell: bash
        run: ${{ steps.adapter.outputs.cmd_sample }}

      - name: Run mutation
        if: steps.adapter.outputs.should_run == 'true' && steps.plan.outputs.should_run == 'true'
        id: run
        continue-on-error: true
        shell: bash
        env:
          MUTATION_SAMPLE_FILES: ${{ steps.sample.outputs.sample_files }}
          MUTATION_SAMPLE_SEED: ${{ github.run_id }}:${{ steps.plan.outputs.base_sha }}..${{ steps.plan.outputs.head_sha }}
          MUTATION_SCORE_BREAK: ${{ steps.adapter.outputs.score_break }}
        run: |
          set -o pipefail
          mkdir -p "$(dirname "${{ steps.adapter.outputs.run_log }}")"
          if [[ "${{ steps.plan.outputs.mode }}" == "dry-run" ]]; then
            ${{ steps.adapter.outputs.cmd_dry_run }} 2>&1 | tee "${{ steps.adapter.outputs.run_log }}"
          else
            ${{ steps.adapter.outputs.cmd_full }} 2>&1 | tee "${{ steps.adapter.outputs.run_log }}"
          fi

      - name: Summarize mutation report
        if: always() && steps.adapter.outputs.should_run == 'true' && steps.plan.outputs.should_run == 'true' && steps.plan.outputs.mode == 'full' && steps.adapter.outputs.cmd_summary != ''
        id: summary
        env:
          MUTATION_SCORE_BREAK: ${{ steps.plan.outputs.mode == 'full' && steps.adapter.outputs.score_break || '' }}
        shell: bash
        run: ${{ steps.adapter.outputs.cmd_summary }}

      - name: Upload mutation report
        if: always() && steps.adapter.outputs.should_run == 'true' && steps.plan.outputs.should_run == 'true'
        uses: actions/upload-artifact@v4
        with:
          name: mutation-report
          path: |
            ${{ steps.adapter.outputs.summary_md }}
            ${{ steps.adapter.outputs.sample_md }}
            ${{ steps.adapter.outputs.run_log }}
            reports/mutation
          if-no-files-found: ignore
          retention-days: 14

      - name: Open or update mutation issue
        if: always() && steps.adapter.outputs.should_run == 'true' && steps.plan.outputs.should_run == 'true' && steps.plan.outputs.mode == 'full' && steps.adapter.outputs.auto_issue_enabled == 'true' && (steps.run.outcome == 'failure' || steps.summary.outcome == 'failure')
        uses: actions/github-script@v8
        env:
          SUMMARY_PATH: ${{ steps.adapter.outputs.summary_md }}
          SAMPLE_PATH: ${{ steps.adapter.outputs.sample_md }}
          RUN_LOG_PATH: ${{ steps.adapter.outputs.run_log }}
          ISSUE_TITLE: ${{ steps.adapter.outputs.auto_issue_title }}
          ISSUE_LABEL: ${{ steps.adapter.outputs.auto_issue_label }}
          MARKER_TOKEN: ${{ steps.adapter.outputs.auto_issue_marker_token }}
          # `Run mutation` is continue-on-error, so its `conclusion` reads `success`
          # in the REST API and the run UI even when it exited non-zero. Only
          # `outcome` carries the truth, and only inside a workflow expression --
          # so it is carried into the issue body here. Without it, a reader triaging
          # from the run summary concludes the mutation commands succeeded and that
          # the reported failure is downstream.
          RUN_OUTCOME: ${{ steps.run.outcome }}
          SUMMARY_OUTCOME: ${{ steps.summary.outcome }}
          SAMPLE_OUTCOME: ${{ steps.sample.outcome }}
        with:
          script: |
            const fs = require('node:fs');
            const title = process.env.ISSUE_TITLE;
            const label = process.env.ISSUE_LABEL;
            const { owner, repo } = context.repo;
            const marker = `<!-- ${owner}/${repo}-${process.env.MARKER_TOKEN} -->`;
            const RECOVERY_CANDIDATE_LABEL = 'mutation-recovered-candidate';
            const runUrl = `${context.serverUrl}/${owner}/${repo}/actions/runs/${context.runId}`;
            // Declared HERE, above every use. A previous revision read this const at
            // the log-tail condition while declaring it 20 lines lower, which is a
            // temporal-dead-zone ReferenceError -- and `||` short-circuiting hid it
            // whenever the summary file was ABSENT, so the only runs that threw were
            // the ones with a summary. The step died before filing anything at all.
            const runOutcome = process.env.RUN_OUTCOME || 'unknown';
            const summaryPath = process.env.SUMMARY_PATH;
            const summary = summaryPath && fs.existsSync(summaryPath)
              ? fs.readFileSync(summaryPath, 'utf8')
              : 'No mutation summary was generated. Check the workflow logs.';
            const samplePath = process.env.SAMPLE_PATH;
            const sample = samplePath && fs.existsSync(samplePath)
              ? fs.readFileSync(samplePath, 'utf8')
              : 'No mutation sample manifest was generated.';
            const runLogPath = process.env.RUN_LOG_PATH;
            let runLogTail = '';
            // ALSO when the mutation commands failed, not only when the summary is
            // absent. A summary can exist and describe a collateral symptom, in which
            // case an absence-only branch never fires and the actual failing baseline
            // output never reaches the issue. A summary that exists is not a summary
            // that explains.
            if (!summaryPath || !fs.existsSync(summaryPath) || runOutcome !== 'success') {
              if (runLogPath && fs.existsSync(runLogPath)) {
                const logText = fs.readFileSync(runLogPath, 'utf8');
                // Clamped by CHARACTERS as well as lines. GitHub rejects a body over
                // 65536 and the throw kills this whole reporting step -- so without a
                // clamp the runs with the MOST diagnostic output are the ones that
                // file no issue at all.
                let tail = logText.split('\n').slice(-80).join('\n');
                if (tail.length > 8000) {
                  tail = `... (truncated to the last 8000 characters)\n${tail.slice(-8000)}`;
                }
                // `Run mutation` creates the log with `tee` BEFORE the command runs, so a
                // command that dies at process launch leaves a 0-byte file. An empty fenced
                // block reads as "we looked and the run produced nothing", which is
                // indistinguishable from "the tail branch is broken again" -- the exact
                // ambiguity this section exists to remove.
                // Two empty cases, not one. A whole-file emptiness claim from evidence
                // about the LAST 80 LINES is the same overclaim this section exists to
                // remove: a 500-line log whose ImportError sits at line 100 followed by
                // blank lines would read as "the commands produced no output", and a
                // triager would stop there.
                const emptyNote = logText.trim() === ''
                  ? '(the run log exists but is empty; the mutation commands produced no output)'
                  : '(the last 80 lines of the run log are blank; read the full log in the `mutation-report` artifact of this run)';
                runLogTail = tail.trim() === ''
                  ? ['', '## Run log tail (last 80 lines)', '', emptyNote].join('\n')
                  : ['', '## Run log tail (last 80 lines)', '', '```', tail, '```'].join('\n');
              }
            }
            // THREE states, not two. `Run mutation` has no `always()`, so when
            // `Select mutation sample` fails the run step is SKIPPED and its outcome
            // is 'skipped' -- and a two-way branch then told the reader "the mutation
            // commands completed" for a run in which they never started. That is the
            // same false-headline class this section exists to fix, so the sample
            // step gets its own line too: on that path it is the only outcome that
            // names what failed.
            const verdictLine = runOutcome === 'failure'
              ? 'The mutation commands themselves failed. Everything the summary below reports about a missing report or missing stats is COLLATERAL — read the run log tail first.'
              : runOutcome === 'skipped'
                ? 'The mutation commands NEVER RAN — an earlier step failed or was skipped. The summary below describes absent artifacts, not a mutation result; read the `Select mutation sample` outcome above and the workflow logs.'
                : runOutcome === 'success'
                  ? 'The mutation commands completed; the failure below is the summary\'s own verdict.'
                  : `\`Run mutation\` reported \`${runOutcome}\`; treat the summary below as UNEXPLAINED rather than as a mutation result.`;
            const stepOutcomes = [
              '## Step outcomes',
              '',
              `- \`Select mutation sample\`: **${process.env.SAMPLE_OUTCOME || 'unknown'}**`,
              `- \`Run mutation\`: **${runOutcome}**`,
              `- \`Summarize mutation report\`: **${process.env.SUMMARY_OUTCOME || 'unknown'}**`,
              '',
              verdictLine,
            ].join('\n');
            const clampBody = (text) => text.length <= 60000
              ? text
              : `${text.slice(0, 60000)}\n\n... (body truncated at 60000 characters; the full summary, sample, and run log are in the \`mutation-report\` artifact of this run)`;
            // Diagnostics FIRST, because `clampBody` truncates from the front. With the
            // log tail last, a large summary consumed the whole budget and the tail was
            // sliced away -- so the D repair silently disabled the B repair for exactly
            // the population B is about: the runs with the most diagnostic output, whose
            // summary describes a collateral symptom while the log names the real failure.
            const unmeasured = /- Status: \*\*UNMEASURED\*\*/.test(summary);
            const lead = (unmeasured || runOutcome === 'skipped')
              ? `Mutation run did not measure on \`${context.sha}\`. This is not a scored mutation regression; read the blocking signal and step outcomes.`
              : `Mutation testing failed on \`${context.sha}\`.`;
            const body = [
              marker,
              lead,
              '',
              `Workflow run: ${runUrl}`,
              '',
              stepOutcomes,
              runLogTail,
              '',
              summary,
              '',
              sample,
            ].join('\n');
            // APPLIED, not merely defined. GitHub rejects a body over 65536 and the
            // throw kills this whole reporting step, so an unclamped body means the
            // runs with the most diagnostic output are the ones that file nothing.
            const clampedBody = clampBody(body);

            try {
              await github.rest.issues.createLabel({
                owner,
                repo,
                name: label,
                color: 'b60205',
                description: 'Automated mutation testing findings',
              });
            } catch (error) {
              if (error.status !== 422) {
                throw error;
              }
            }

            // Not the search endpoint: `in:title` is full-text, so it selects human-filed
            // issues that merely share the label and title words; results are relevance-
            // truncated; and the search index lags issue creation by minutes. Each of those
            // files a duplicate. Listing by label and selecting on the marker this workflow
            // itself wrote is exact, complete, and read-your-writes current.
            const openIssues = await github.paginate(github.rest.issues.listForRepo, {
              owner,
              repo,
              state: 'open',
              labels: label,
              per_page: 100,
            });
            const existing = openIssues.find(
              (issue) => !issue.pull_request && (issue.body || '').includes(marker),
            );

            if (existing) {
              await github.rest.issues.createComment({
                owner,
                repo,
                issue_number: existing.number,
                body: clampedBody,
              });
              // A fresh failure retires any standing recovery candidate.
              try {
                await github.rest.issues.removeLabel({
                  owner,
                  repo,
                  issue_number: existing.number,
                  name: RECOVERY_CANDIDATE_LABEL,
                });
              } catch (error) {
                if (error.status !== 404) {
                  throw error;
                }
              }
            } else {
              await github.rest.issues.create({
                owner,
                repo,
                title,
                labels: [label],
                body: clampedBody,
              });
            }

      - name: Comment mutation recovery candidate
        # Only a scheduled run may report recovery: workflow_dispatch computes no
        # base_sha, so its changed-line classifier is inert and a dispatch-green
        # run cannot speak to a changed-line regression at all.
        #
        # This step records a recovery CANDIDATE and never changes issue state. The
        # green is this job's own evidence channel read by this job's own observer,
        # and the sample seed rotates per run, so a green may not have mutated the
        # same file population as the run that filed the issue, and does not verify
        # the surviving mutant that opened it. Closing on that would be a
        # machine declaring completion at an irreversible boundary. The close belongs
        # to a distinct observer reading the observables this comment carries.
        if: github.event_name == 'schedule' && steps.adapter.outputs.should_run == 'true' && steps.plan.outputs.should_run == 'true' && steps.plan.outputs.mode == 'full' && steps.adapter.outputs.auto_issue_enabled == 'true' && steps.run.outcome == 'success' && (steps.summary.outcome == 'success' || steps.adapter.outputs.cmd_summary == '')
        uses: actions/github-script@v8
        env:
          SAMPLE_PATH: ${{ steps.adapter.outputs.sample_md }}
          ISSUE_LABEL: ${{ steps.adapter.outputs.auto_issue_label }}
          MARKER_TOKEN: ${{ steps.adapter.outputs.auto_issue_marker_token }}
          RUN_MODE: ${{ steps.plan.outputs.mode }}
        with:
          script: |
            const fs = require('node:fs');
            const label = process.env.ISSUE_LABEL;
            const { owner, repo } = context.repo;
            const marker = `<!-- ${owner}/${repo}-${process.env.MARKER_TOKEN} -->`;
            const RECOVERY_CANDIDATE_LABEL = 'mutation-recovered-candidate';
            const runUrl = `${context.serverUrl}/${owner}/${repo}/actions/runs/${context.runId}`;
            const samplePath = process.env.SAMPLE_PATH;
            const sample = samplePath && fs.existsSync(samplePath)
              ? fs.readFileSync(samplePath, 'utf8')
              : 'No mutation sample manifest was generated for this green run.';

            // Listed by label rather than searched, for the same reasons as the open step.
            // Only issues carrying this workflow's marker are its own to annotate.
            const openIssues = await github.paginate(github.rest.issues.listForRepo, {
              owner,
              repo,
              state: 'open',
              labels: label,
              per_page: 100,
            });
            const mine = openIssues.filter(
              (issue) => !issue.pull_request && (issue.body || '').includes(marker),
            );

            const body = [
              `Scheduled mutation run passed on \`${context.sha}\` (mode \`${process.env.RUN_MODE}\`).`,
              '',
              `Workflow run: ${runUrl}`,
              '',
              'This is a recovery **candidate**, not a verdict. The sample seed rotates per',
              'run, so this green may not have mutated the same file population as the run',
              'that filed this issue, and it does not verify that the specific surviving',
              'mutant reported above is dead. Close only once a distinct observer has',
              'confirmed it.',
              '',
              sample,
            ].join('\n');

            for (const issue of mine) {
              const labelled = (issue.labels || []).some(
                (entry) => (typeof entry === 'string' ? entry : entry.name) === RECOVERY_CANDIDATE_LABEL,
              );
              // One candidate comment per recovery, not one per scheduled cycle.
              if (labelled) {
                continue;
              }
              // Annotating is best-effort: a locked or transferred issue must not turn a
              // GREEN mutation run red. `core.error` cannot fail the run either, but a
              // systematically unpopulated evidence record is the P5 failure that has to
              // stay loud, so it is never downgraded to a warning.
              try {
                await github.rest.issues.createComment({
                  owner,
                  repo,
                  issue_number: issue.number,
                  body,
                });
              } catch (error) {
                core.error(`could not comment the recovery candidate on #${issue.number}: ${error.message}`);
                continue;
              }
              // Separately caught: the label is the dedupe key, so a comment that landed
              // without its label would silently re-post on every later scheduled green.
              try {
                await github.rest.issues.addLabels({
                  owner,
                  repo,
                  issue_number: issue.number,
                  labels: [RECOVERY_CANDIDATE_LABEL],
                });
              } catch (error) {
                core.error(`commented #${issue.number} but could not apply ${RECOVERY_CANDIDATE_LABEL}; a later green may repeat the comment: ${error.message}`);
              }
            }

      - name: Fail workflow on mutation failure
        if: steps.adapter.outputs.should_run == 'true' && steps.plan.outputs.should_run == 'true' && (steps.run.outcome == 'failure' || steps.summary.outcome == 'failure')
        run: exit 1

