test("rejects a non-plain-object usage value even when it is truthy and carries token-shaped properties", () => {
	// `isObjectRecord` requires `typeof value === "object"`, not just
	// truthiness + non-array. A function is truthy, is not an array, and (like
	// any object) can carry arbitrary own properties — this is the one shape
	// that distinguishes the typeof check from a truthiness-only check: those
	// properties must NOT leak into the telemetry, or `usage` is being treated
	// as if it were a record when it is not.
	const usageLikeFunction = () => {};
	usageLikeFunction.input_tokens = 7;
	usageLikeFunction.output_tokens = 3;

	assert.deepEqual(extractClaudeTelemetry({ usage: usageLikeFunction }), {
		provider: "anthropic",
	});
});

test("omits invalid Claude telemetry counters without fabricating totals", () => {
	const arrayUsage = [];
	arrayUsage.input_tokens = 9;
	arrayUsage.output_tokens = 9;

	assert.deepEqual(
		extractClaudeTelemetry({
			usage: {
				input_tokens: -1,
				cache_creation_input_tokens: 1.5,
				cache_read_input_tokens: "3",
				output_tokens: -2,
			},
			total_cost_usd: -0.1,
		}),
		{
			provider: "anthropic",
		},
	);
	assert.deepEqual(extractClaudeTelemetry({ usage: arrayUsage }), {
		provider: "anthropic",
	});
	assert.deepEqual(extractClaudeTelemetry({ usage: null }), {
		provider: "anthropic",
	});
	assert.deepEqual(extractClaudeTelemetry({ total_cost_usd: "0" }), {
		provider: "anthropic",
	});
	assert.deepEqual(extractClaudeTelemetry({ total_cost_usd: Number.POSITIVE_INFINITY }), {
		provider: "anthropic",
	});

	assert.deepEqual(
		extractClaudeTelemetry({
			usage: {
				input_tokens: 2,
				output_tokens: null,
			},
		}),
		{
			provider: "anthropic",
			prompt_tokens: 2,
			total_tokens: 2,
		},
	);

	assert.deepEqual(
		extractClaudeTelemetry({
			usage: {
				input_tokens: null,
				output_tokens: 5,
			},
		}),
		{
			provider: "anthropic",
			completion_tokens: 5,
			total_tokens: 5,
		},
	);

	assert.deepEqual(
		extractClaudeTelemetry({
			usage: {
				output_tokens: 0,
			},
			total_cost_usd: 0,
		}),
		{
			provider: "anthropic",
			completion_tokens: 0,
			total_tokens: 0,
			cost_usd: 0,
		},
	);
});

