test("read-only Claude runner enforces tools, config isolation, and cleanup", () => {
	withTempDir((dir) => {
		const options = { workspace: dir, repoRoot: dir, timeoutMs: 1000 };
		const stdout = JSON.stringify({ result: JSON.stringify(observedFixture()) });
		const { calls, spawn } = recordingSpawn({ status: 0, stdout, stderr: "" });

		runClaudeEvaluation(options, evaluationFixture(dir), dir, SEAM_STARTED_AT, spawn);

		const { args, spawnOptions } = calls[0];
		assert.ok(args.includes("--restricted"));
		assert.deepEqual(args.slice(args.indexOf("--tools"), args.indexOf("--permission-mode")), [
			"--tools",
			"Read,Glob,Grep",
		]);
		assert.deepEqual(args.slice(args.indexOf("--permission-mode"), args.indexOf("--permission-prompts")), [
			"--permission-mode",
			"plan",
		]);
		assert.ok(args.includes("--bare"));
		assert.ok(args.includes("--safe-mode"));
		assert.notEqual(spawnOptions.env.HOME, dir);
		assert.equal(existsSync(spawnOptions.env.HOME), false);
		assert.equal(spawnOptions.env.OPENAI_API_KEY, undefined);
	});
});

test("read-only Claude runner nests its home beneath an explicit owned root", () => {
	withTempDir((dir) => {
		const ownedRoot = join(dir, "owned-root");
		mkdirSync(ownedRoot);
		const options = { workspace: dir, repoRoot: dir, timeoutMs: 1000 };
		const stdout = JSON.stringify({ result: JSON.stringify(observedFixture()) });
		const { calls, spawn } = recordingSpawn({ status: 0, stdout, stderr: "" });
		const previousRoot = process.env.CHARNESS_OWNED_SCRATCH_ROOT;
		process.env.CHARNESS_OWNED_SCRATCH_ROOT = ownedRoot;
		try {
			runClaudeEvaluation(options, evaluationFixture(dir), dir, SEAM_STARTED_AT, spawn);
		} finally {
			if (previousRoot === undefined) {
				delete process.env.CHARNESS_OWNED_SCRATCH_ROOT;
			} else {
				process.env.CHARNESS_OWNED_SCRATCH_ROOT = previousRoot;
			}
		}

		assert.ok(calls[0].spawnOptions.env.HOME.startsWith(`${ownedRoot}/`));
		assert.equal(calls[0].spawnOptions.env.CHARNESS_OWNED_SCRATCH_ROOT, ownedRoot);
		assert.equal(existsSync(calls[0].spawnOptions.env.HOME), false);
		assert.equal(existsSync(ownedRoot), true);
	});
});

test("read-only Claude invocations use distinct homes beneath one owned root", () => {
	withTempDir((dir) => {
		const ownedRoot = join(dir, "owned-root");
		mkdirSync(ownedRoot);
		const options = { workspace: dir, repoRoot: dir, timeoutMs: 1000 };
		const stdout = JSON.stringify({ result: JSON.stringify(observedFixture()) });
		const { calls, spawn } = recordingSpawn({ status: 0, stdout, stderr: "" });
		const previousRoot = process.env.CHARNESS_OWNED_SCRATCH_ROOT;
		process.env.CHARNESS_OWNED_SCRATCH_ROOT = ownedRoot;
		try {
			runClaudeEvaluation(options, evaluationFixture(dir), dir, SEAM_STARTED_AT, spawn);
			runClaudeEvaluation(options, evaluationFixture(dir), dir, SEAM_STARTED_AT, spawn);
		} finally {
			if (previousRoot === undefined) delete process.env.CHARNESS_OWNED_SCRATCH_ROOT;
			else process.env.CHARNESS_OWNED_SCRATCH_ROOT = previousRoot;
		}
		const homes = calls.map((call) => call.spawnOptions.env.HOME);
		assert.equal(new Set(homes).size, 2);
		assert.ok(homes.every((home) => home.startsWith(`${ownedRoot}/claude-eval-home-`)));
		assert.ok(homes.every((home) => !existsSync(home)));
		assert.equal(existsSync(ownedRoot), true);
	});
});

